{
  "schema_version": "spine_v1",
  "chapters": [
    {
      "chapter_id": 1,
      "title": "Tutorials are for People Who Can't Read",
      "goal": "Survive the 'Impossible' tutorial boss by exploiting a clipping error in the arena geometry.",
      "chapter_role": "hook",
      "stakes_shift": "From a confused casualty to a high-level outlier with a broken stat sheet.",
      "bridge": {
        "from_prev": "Arrival in the system's death-trap tutorial.",
        "to_next": "Finding a place to hide and process the loot while the system tries to recalibrate."
      },
      "pacing": {
        "intensity": 4,
        "tempo": "rush",
        "expected_scene_count": 8
      }
    },
    {
      "chapter_id": 2,
      "title": "Luck is a Valid Skill Tree",
      "goal": "Dump all attribute points into Luck and find a starting town that won't arrest a 'glitch' on sight.",
      "chapter_role": "setup",
      "stakes_shift": "From accidental survivor to intentional system-breaker.",
      "bridge": {
        "from_prev": "Escaping the tutorial zone with unintended rewards.",
        "to_next": "Identifying a high-value target that only a high-luck build can reach."
      },
      "pacing": {
        "intensity": 2,
        "tempo": "steady",
        "expected_scene_count": 10
      }
    },
    {
      "chapter_id": 3,
      "title": "The Unbreakable Vault is Actually a Suggestion",
      "goal": "Infiltrate the local Merchant Guild's 'impenetrable' storage using a combination of high crit-rate and bad physics.",
      "chapter_role": "investigation",
      "stakes_shift": "From a petty nuisance to a high-priority target for the local authorities.",
      "bridge": {
        "from_prev": "Entering the trade hub under a false identity.",
        "to_next": "A massive bounty is placed on the 'Ghost of the Vault' leading to a chase."
      },
      "pacing": {
        "intensity": 3,
        "tempo": "steady",
        "expected_scene_count": 12
      }
    },
    {
      "chapter_id": 4,
      "title": "Aggro Management for the Socially Anxious",
      "goal": "Outrun a coordinated hunting party by leading them into a high-level monster den.",
      "chapter_role": "pressure",
      "stakes_shift": "The protagonist realizes they can't just run; they need to become the hunter.",
      "bridge": {
        "from_prev": "Being cornered by the Merchant Guild's elite enforcers.",
        "to_next": "Discovering a world-boss that is currently vulnerable to a specific exploit."
      },
      "pacing": {
        "intensity": 5,
        "tempo": "rush",
        "expected_scene_count": 10
      }
    },
    {
      "chapter_id": 5,
      "title": "Gravity: The Ultimate Boss Killer",
      "goal": "Lure the regional World Boss to a cliff edge and use a low-level knockback skill to trigger a fall-damage overflow.",
      "chapter_role": "reversal",
      "stakes_shift": "Achieving a feat that triggers a global system announcement, ending anonymity.",
      "bridge": {
        "from_prev": "Setting the trap at the Peak of Despair.",
        "to_next": "Dealing with the fallout of being the first 'Level 1' to kill a God-tier mob."
      },
      "pacing": {
        "intensity": 4,
        "tempo": "steady",
        "expected_scene_count": 10
      }
    },
    {
      "chapter_id": 6,
      "title": "The Patch is Coming",
      "goal": "Confront the 'Hero' party sent by the System to 'fix' the protagonist before the upcoming server maintenance.",
      "chapter_role": "confrontation",
      "stakes_shift": "The conflict moves from survival to a fight for the right to exist in the world.",
      "bridge": {
        "from_prev": "The sky turning red as the 'System Update' countdown begins.",
        "to_next": "The final stand at the world's edge to reach the 'Unpatched' zone."
      },
      "pacing": {
        "intensity": 5,
        "tempo": "rush",
        "expected_scene_count": 12
      }
    },
    {
      "chapter_id": 7,
      "title": "Escape to the Outlands",
      "goal": "Cross the border into the lawless 'Beta-Test' region where the System's rules are non-binding.",
      "chapter_role": "climax",
      "stakes_shift": "Total freedom from the System's constraints, but at the cost of being an eternal outlaw.",
      "bridge": {
        "from_prev": "Breaking through the final barrier of the Hero party.",
        "to_next": "Disappearing into the fog of the unmapped territories."
      },
      "pacing": {
        "intensity": 5,
        "tempo": "rush",
        "expected_scene_count": 8
      }
    }
  ]
}

